export const FEAT_TYPES: FeatType[] = ['combat', 'general', 'metamagic', 'item_creation', 'teamwork', 'critical', 'style', 'race', 'story']

export function getFeatById(id: string): Feat | undefined {
  return FEATS.find(feat => feat.id === id)
}
